// app/Models/User.php
protected $fillable = ['name', 'email'];   // is_admin is NOT here

// app/Http/Controllers/ProfileController.php
public function update(Request $request)
{
    $data = $request->validate([
        'name'  => ['required', 'string', 'max:100'],
        'email' => ['required', 'email', 'max:190'],
    ]);
    $request->user()->update($data);   // validated keys only

    // raw SQL still uses bindings
    $rows = DB::select('select id, name from users where email = ?', [$data['email']]);
    return back();
}

// DON'T: User::create($request->all());  with  protected $guarded = [];

